import {ToolRegistry} from './registry.js';
import Ajv, {type ValidateFunction} from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry input validation', () => {
  it('compiles a static tool schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );
    try {
      for (let call = 0; call < 10; call += 1) await registry.execute('get_weather', {location: 'Oslo'});

      const compileCallCount = compile.mock.calls.length;
      expect({compileCallCount, executorCalls}).toEqual({compileCallCount: 1, executorCalls: 10});
    } finally {
      compile.mockRestore();
    }
  });

  it('normalizes legacy nested validation paths before reporting required properties', async () => {
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'required',
          dataPath: '.address',
          params: {missingProperty: 'city/name'},
        },
      ],
    }) as unknown as ValidateFunction;
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validator);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {'city/name': {type: 'string'}},
              required: ['city/name'],
            },
          },
        },
      },
      async () => 'sunny'
    );

    try {
      const response = await registry.execute('get_weather', {address: {}});

      expect(response.result).toBe('Input property /address/city~1name is required');
    } finally {
      compile.mockRestore();
    }
  });

  it('formats legacy nested type-error paths as JSON pointers', async () => {
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'type',
          dataPath: '.address.city',
          params: {type: 'string'},
        },
      ],
    }) as unknown as ValidateFunction;
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockReturnValue(validator);
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object'},
      },
      async () => 'sunny'
    );

    try {
      const response = await registry.execute('get_weather', {address: {city: 42}});

      expect(response.result).toBe('Input property /address/city must be string');
    } finally {
      compile.mockRestore();
    }
  });

  it('names the full path of a missing nested required property', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
          required: ['address'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {address: {}});

    expect({result: response.result, executorCalls}).toEqual({
      result: 'Input property /address/city is required',
      executorCalls: 0,
    });
  });

  it('uses the current function-valued schema and reuses validators by schema object', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    let executorCalls = 0;
    const firstSchema = {type: 'object', properties: {first: {type: 'string'}}, required: ['first']};
    const secondSchema = {type: 'object', properties: {second: {type: 'number'}}, required: ['second']};
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'Dynamic schema',
        inputSchema: definitionCalls++ < 2 ? firstSchema : secondSchema,
      }),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const first = await registry.execute('dynamic_tool', {first: 'yes'});
    const staleSchemaRejected = await registry.execute('dynamic_tool', {first: 'yes'});
    const second = await registry.execute('dynamic_tool', {second: 2});

    try {
      const compileCallCount = compile.mock.calls.length;
      expect({
        results: [first.result, staleSchemaRejected.result, second.result],
        compileCallCount,
        executorCalls,
      }).toEqual({
        results: ['ok', 'Input property /second is required', 'ok'],
        compileCallCount: 2,
        executorCalls: 2,
      });
    } finally {
      compile.mockRestore();
    }
  });
});
import type {ToolDefinition} from '../../types/ai.js';
import Ajv, {type ValidateFunction} from 'ajv';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ValidateFunction>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private compile(schema: object): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.ajv.compile(schema);
    this.validators.set(schema, validator);
    return validator;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validationPath(error: {instancePath?: string; dataPath?: string} | undefined): string {
    if (error?.instancePath) return error.instancePath;
    const legacyPath = error?.dataPath || '';
    if (!legacyPath.startsWith('.')) return legacyPath;
    const segments = legacyPath
      .slice(1)
      .replace(/\[(\d+)\]/g, '.$1')
      .split('.')
      .filter(Boolean);
    return `/${segments.join('/')}`;
  }

  private validationError(validator: ValidateFunction): string {
    const error = validator.errors?.[0] as
      | {
          keyword?: string;
          instancePath?: string;
          dataPath?: string;
          params?: {missingProperty?: string; type?: string};
        }
      | undefined;
    const path = this.validationPath(error);
    const missingProperty = error?.params?.missingProperty;
    if (error?.keyword === 'required' && missingProperty) {
      const escapedProperty = missingProperty.replace(/~/g, '~0').replace(/\//g, '~1');
      return `Input property ${path}/${escapedProperty} is required`;
    }
    const expected = typeof error?.params?.type === 'string' ? error.params.type : (error?.keyword ?? 'valid');
    return `Input property ${path || '/'} must be ${expected}`;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates schema input and returns rejections; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator: ValidateFunction;
    try {
      validator = tool.validator ?? this.compile(definition.inputSchema);
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${String(error)}`, {cause: error});
    }
    if (!validator(input)) return {result: this.validationError(validator)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When a nested object omits a required property, the rejection names the complete path from the root object and does not invoke the executor ([validated by: names the full path of a missing nested required property](../../src/orchestration/tools/registry.test.ts#L100), [legacy nested paths](../../src/orchestration/tools/registry.test.ts#L32)).
- Legacy validator errors with nested dot paths are reported as complete JSON Pointer paths ([validated by: formats legacy nested type-error paths as JSON pointers](../../src/orchestration/tools/registry.test.ts#L70)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static tool schema once across repeated executions](../../src/orchestration/tools/registry.test.ts#L6)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: uses the current function-valued schema and reuses validators by schema object](../../src/orchestration/tools/registry.test.ts#L133)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
